/* KnowledgeFoundry user guide website: appearance, the Sections button on a phone, and search. Guide text is never used as markup. */
(function () {
  var root = document.documentElement;
  root.classList.add('js');
  var KEY = 'kf-guide-look';
  function applyLook(look) {
    if (look === 'light' || look === 'dark') root.setAttribute('data-theme', look); else root.removeAttribute('data-theme');
  }
  var saved = null;
  try { saved = localStorage.getItem(KEY); } catch (e) { /* storage blocked: follow the system */ }
  applyLook(saved);

  /* The words of every section, lowercase, in section order (filled in when the site is built). */
  var TEXT = ["the workspace the window has four areas. across the top, the design, build, sound and publish tabs hold the tools for each stage of the work, roughly in the order you need them. on the left is the flow canvas, where the course's screens and logic are cards joined by wires. in the middle is the screen preview stage, where you lay out the selected screen, with the timeline under it. on the right are the panels: properties, layers, triggers, variables, captions, templates, assets and validation (see switch the right-hand panels). the knowledgefoundry window with the safety first example open: the design, build, sound and publish tabs across the top, the screen preview stage and its timeline in the middle, the flow canvas below them, and the properties panel and the rail of panel tabs on the right menus: the design, build, sound and publish menus hold the same tools as the tabs, so you can also reach them with the keyboard (press alt, then the arrow keys). where a project opens: a file you have saved on this computer opens on the screen you had selected when you last saved it. a file new to this computer, such as one a colleague sent or an example course, opens on the course's first screen. search for any command: press ctrl+k and type what you want to do, such as \"glossary\" or \"export\". every command in the app is listed there, with its shortcut. undo (ctrl+z) and redo (ctrl+y) cover every change to the course, including changes made in dialogs. in every dialog, tab and shift+tab stay inside the dialog, and when it closes focus goes back to the button that opened it. a message in the status line at the bottom goes away when it is no longer true: a prompt such as select a screen first when you select something, and a message about a change or a save when you edit the course again. new project (ctrl+n) starts a small working course: a start card, a welcome screen and a complete card, already wired.","example courses three finished courses come with knowledgefoundry, to open, take apart and borrow from. choose help → example courses and pick one. the first time, it's copied to your documents\\knowledgefoundry examples folder and that copy opens, so you can change and save it freely; the original that comes with the app never changes. next time you choose it, your copy opens with your changes. course what it shows safety first branching on the learner's choice, variables shown in text, triggers and states, a formula that gates continue, pop-ups on a floor plan, practice checks and a scored final drawn from a question bank by category, most question types, a retry path and a certificate handling a difficult call narration with captions, a video with captions, markers that reveal items as the narrator speaks, a sound played by a trigger, animation and keyframes, branching feedback, a short scored check your first week every ready-made interaction (timeline, tabs, labeled graphic, accordion, flash cards, process steps, a picture that opens larger), a glossary, a file to download, a panel overlay, a button that stays disabled until a file is downloaded, and a survey with rating questions","your project is one file a project is a single .kfoundry file. it holds the course and everything it uses: the pictures, sound, video and files you added. nothing sits beside it, so you can copy it, email it, or put it in a shared folder as one file. ctrl+s saves it, and save as makes a copy under a new name. saving is safe. the app writes a complete new file and swaps it in when it is finished, so a crash while saving never leaves half a project. it is a zip. like a word document, the file is really a zip. if you ever need to look inside, make a copy, rename the copy to end in .zip and open it: project.json is the course and the assets folder holds the files. rename it back to .kfoundry to use it again. older projects. a project saved by an earlier version (a plain text .kfoundry file with a .assets folder next to it) is not opened by this version. exporting is separate. exporting a course for an lms makes its own package and does not change your project file.","open a recent project choose file > open recent to reopen one of the last ten projects you opened or saved, newest first. if you have unsaved changes you are asked first, as with open. a project that has been moved or deleted is taken off the list. clear recent list at the bottom empties it. the list belongs to this computer and is not saved in your courses.","switch the right-hand panels the panels on the right (properties, layers, triggers, variables, captions, templates, assets and validation) are named tabs down the right edge, like a rail. one panel is open at a time. choose a tab to open its panel beside the rail. choose the open tab again to close the panel and give the stage the room. choose any tab to bring it back. view > panels and the command search (ctrl+k) open a panel too, even when it is closed. reset layout puts everything back as it started.","choose light or dark (appearance) the editor can look light, dark or like your computer. this changes only the editor you work in. the course on the stage, the live preview and the finished course keep the colors you gave them. open appearance in the bottom right corner of the window and choose light, dark or system (follow windows). you can also use view > appearance, or press ctrl+k and type \"appearance\". system is the choice you start with. it uses the windows setting, and the editor changes by itself when windows changes between light and dark. the choice is remembered on this computer and is not saved in your courses, so a course looks the same when someone else opens it.","build the course flow (the flow canvas) the flow canvas is the course's map. each card is a step, and the wires between them decide what comes next. nothing is hidden: if a learner can get somewhere, there is a wire that shows it. the flow canvas of the safety first example: start leads to the welcome screen, a role choice, a knowledge check and a condition that branches to one of two lessons, then a scored final assessment with passed and failed paths card what it does start where the course begins. a course has one. screen a page the learner sees. each button (or clickable item) on it adds an output socket to the card. condition tests a variable, or a formula, and leaves by true or false. set variable sets, adds to, takes away from or switches a variable, then carries on. question one question written on the card. leaves by correct or incorrect. quiz asks questions drawn from the question bank (see build a quiz). results shows the score. leaves by passed, failed or retry. complete ends the course as completed, passed or failed, and can report a score. add a card: right-click an empty spot on the canvas, use the build tab, or press ctrl+k and type \"add\". wire two cards: drag from an output socket on the right of one card to the next card. to remove a wire, select it and press delete. move around: scroll to zoom, hold space and drag to pan, and use the mini-map in the corner. tidy it: see tidy up the flow canvas. a card that nothing leads to, or a button with no wire, is listed by the checks (see check the course for problems).","tidy up the flow canvas when the cards on the flow canvas get messy, press ⇶ tidy up (top left of the canvas), or press ctrl+k and type \"tidy\". the cards are arranged left to right: start first, then each card to the right of the cards that lead to it. a condition's true branch sits above its false branch, and a wire that loops back is drawn backward without disturbing the order. cards that are not wired to the main flow are placed in their own rows below it. only positions change, never the wires or settings. undo puts the cards back where they were. the ⇶ tidy up ▾ button opens a short menu: tidy up (the arrangement above) and compact tidy up. compact tidy up packs the cards closer and folds a long flow into rows that zig zag: the first row runs left to right, the next runs right to left underneath it, and so on. the end of one row sits above the start of the next, so the whole flow fits in a smaller space. a short flow stays in one row.","start from a template the templates panel holds ready-made screen layouts. each card shows a thumbnail, how many items it has and how many buttons (sockets). add to canvas adds a new screen with that layout. you can also drag a template onto an empty part of the flow canvas. apply to selected gives the selected screen that layout and keeps its wires. you can also drag a template onto a screen card. save your own: right-click a screen card on the flow canvas and choose save as template. name it in the box that appears; the message says where it is saved. your templates sit next to the built-in ones, and ✕ deletes one of yours. applying a template resets the screen's reading order (see set the reading order). quiz pages have templates of their own, under templates… above a quiz page (see build a quiz).","keep values in variables a variable remembers something while the learner works through the course: a choice, a count, a score. open the variables panel and press + variable. give it a name (letters, numbers and _, starting with a letter or _), a type (number, boolean for yes or no, or string for text) and the value it starts with. change it: with a set variable card on the flow, or a trigger action (change a variable). test it: with a condition card or a trigger's only if. show it: put {{name}} in a text item, a button label or alt text (see build a quiz → good to know). rename it: type the new name in the panel. every card, trigger and {{placeholder}} that uses it is updated. while you preview, the panel has a live column with each variable's current value. quizzes keep their own variables up to date, such as quizpercent (see build a quiz).","do math with variables (formulas) a condition node normally compares one variable with one value. to test something more, select the node and change test to formula, then type the test, for example var1 + var2 + var3 >= 2. it passes when the total is at least 2. a set variable node (and the compare to side of a normal condition) can also use a formula: choose formula in the kind-of-value list and type something like bonus * 2 + 1. you can use examples math a + b, a - b, a * 2, a / 4, brackets: (a + b) / 2 comparisons = or ==, !=, \u003c, \u003c=, >, >= combine tests and, or, not: score >= 80 and tries \u003c 3 functions min(a, b), max(a, b), round(x), floor(x), ceil(x), abs(x) true counts as 1 and false as 0, so you can add up yes/no variables: if seena, seenb and seenc are yes/no variables, seena + seenb + seenc >= 2 means at least two were seen. variables hold plain numbers, so a percent such as quizpercent is compared with a plain number: quizpercent >= 80. the words true, false, and, or and not cannot be variable names. under the box, the app says what the formula means, or what is wrong with it. a formula that cannot be worked out while the course runs (for example, dividing by zero) counts as false and never stops the course. export is blocked if a formula has an error (code val-e11), so you find out before you publish.","arrange and animate a screen select a screen on the flow canvas, then work directly on the screen preview stage (top left). the screen preview stage with the title selected: handles around it, the floating palette of text and layout tools below it, and the timeline underneath showing each item's bar and its fade in and zoom in effects to do this do this add an item click text / button / shape / ellipse / image… above the stage, or drag one onto the stage move, resize, rotate drag it; drag the square handles; drag the round handle above it (shift snaps to 15°) edit wording double-click text or a button, type, then click away (esc cancels) colors, font size, alt text use the small toolbar that floats beside the selected item. for a button it also has b, i and u to make the label bold, italic or underlined reorder layers layers tab (right): drag rows. top of the list is in front make something appear later timeline (under the stage): drag its bar right keep something showing until the learner leaves the screen drag the right edge of its bar all the way to the end of the timeline. if the narration is shorter than the screen, also lower the screen's length in the of ___ s box so the timeline ends where the narration does add an entrance or exit effect select the item, move the playhead, choose + animation… animate a move turn on ● auto-key, drag the playhead to a time, then move the item add a star, arrow, speech bubble, heart, ring and more press ✦ shapes above the stage (the rectangle button next to it adds a plain rectangle; shapes has the full palette) and click a shape (or drag it onto the stage). with it selected, the floating toolbar has plain sliders for what can be adjusted: points, point depth, head length, tail position and so on. use outline for an outline and its thickness. change the kind with the shape list show a number as a progress ring or pie add a progress ring or pie, then under show variable in the floating toolbar choose a number variable (for example quizpercent) and the value at which it is full. it fills as the number changes fill a button or shape with a gradient select it, then press gradient next to fill in the floating toolbar. pick from and to colors and an angle (90 = left to right, 180 = top to bottom). press gradient again to go back to one color. check course warns if a button's label is hard to read on it make text, a picture or a shape clickable select it, then in the floating toolbar press acts as button. it gets a socket on the flow canvas. a shape needs a screen reader name, typed in the box that appears preview ▶ in the timeline plays the screen. on the publish tab, preview from start runs the course from the beginning, and preview from here runs it from the screen selected on the flow canvas (what comes before it is skipped, and variables start at their starting values). the flow canvas follows along: it moves to keep the current card in view and keeps its zoom notes: only buttons are clickable by default. any text, picture or shape can be made clickable with acts as button in the floating toolbar (see the table); press it again to turn it back into plain content, which removes its wires. clickable items can be reached with tab and pressed with enter or space, and give a warning if a screen reader would have nothing to announce. buttons are not clickable until they appear. the stage is a fixed 16:9 canvas that scales to fit the window.","the floating palette on the stage select anything on the stage (text, a button, a picture, a shape) and a small palette appears beside it with tools for that kind of item: text style and size, colors (theme colors first), alignment on the screen, ✦ animate…, layer order, lock, hide, duplicate and delete. the palette always stays inside the stage area. drag its ⋮⋮ grip (or any empty part of the palette) to put it somewhere else (it stays there), or focus the grip and press the arrow keys (shift for bigger steps); double-click the grip to make it follow the selection again. select an audio layer to get its own palette: listen, volume, + caption at playhead, ✨ auto-transcribe.","choose where the tools for the selected item appear when you select something on the stage, its tools (fill, text, alignment, animation, lock and so on) appear in a small palette. use the list in the stage's bar to choose where it goes: tools float on the stage (the usual way): the palette floats beside the item. drag its grip to put it somewhere else; double-click the grip to let it follow the item again. tools float over the app: the palette floats over the whole window, so you can drag it over any panel, such as the flow canvas, and keep it there. tools docked at the top: the palette sits in a row at the top of the stage and never covers the screen you are designing. select an item to see its tools; the row keeps its height so the stage does not jump around. the choice is remembered on this computer. it is not part of the course.","select, group and arrange items select several items: hold shift or ctrl and click items on the stage to add or remove them, or drag a rectangle on an empty part of the stage to select everything it touches (hold shift or ctrl to add to what is selected). ctrl+a selects everything on the screen. in the layers panel, shift or ctrl-click does the same. esc, or a click on empty stage, clears the selection. move them together: drag any selected item, or use the arrow keys (shift for bigger steps). the selection snaps to the edges and center of the stage and the other items; hold alt to turn snapping off. align and space: when several items are selected a small palette appears with align buttons (left, center, right, top, middle, bottom) and space evenly (left to right, top to bottom; it needs three or more items). align lines the items up with the edge of the whole selection; with one item selected, align lines it up with the stage. the same actions are in the command search (ctrl+k, type \"align\" or \"space\"), so you can do them without a mouse. stretch and turn them together: with several items selected, the dashed box around them has handles. drag a handle to stretch all of them with the box (shift on a corner keeps the proportions). drag the round handle above it to turn them all together (shift snaps to 15 degrees). edges snap to the stage and to other items while you stretch; hold alt to switch snapping off. equal gaps: while you drag an item, it snaps so the gap beside it matches a gap that is already there, or so it sits midway between two items. pink marks show the equal gaps. select from the keyboard: click the stage, then press alt+right (or alt+down) for the next item and alt+left (or alt+up) for the previous one. add shift to add the item to the selection instead. group: press group (ctrl+g) to tie items together. clicking any item in a group selects the whole group, and the group moves, copies, deletes, stretches and turns together (it gets the same box and handles as any selection). ungroup (ctrl+shift+g) separates them. to change just one item in a group, select it in the layers panel. a group does not change how its items animate or when they appear: each keeps its own timing and effects. a ⛓ in the layers panel marks grouped items. copy and delete: ctrl+d copies the whole selection (the copies are selected, and a copied group becomes a new group), and del deletes it. each action is one undo.","copy, cut and paste items select one or more items on the stage, then press ctrl+c (or edit > copy) to copy them, or ctrl+x to cut them. press ctrl+v to paste. you can paste on the same screen or select another screen first and paste there. each paste lands a little down and to the right of the last one so they do not sit exactly on top of each other. a pasted button is a new button with its own socket on the flow canvas, not wired to anything. items that were grouped are pasted as a new group. ctrl+d (duplicate) still makes a copy right away on the same screen. when you are typing in a text box, copy and paste work on the text as usual. shapes you have not named are listed by their kind in the timeline and the layers panel: rectangle, ellipse, star and so on. if there is more than one of a kind they are numbered, rectangle 1, rectangle 2, in the order you added them. double-click a name in the layers panel to give a shape a name of your own.","set when an item appears and disappears (start and end times) select an item on the stage or on the timeline. its row on the timeline turns amber, and the timeline's toolbar shows its name with starts at and ends at, in seconds. type a time in either box to move that edge of its bar; dragging the bar or its edges still works and the boxes follow. if the item stays until the screen ends, the toolbar says to the end of the screen; type an earlier ends at to end it sooner, or the length of the screen to put it back. for a sound, starts at moves the whole sound and ends at trims it. amber means selected everywhere you pick things from a list: the timeline and the layers panel. layers with the keyboard. tab to a row in the layers panel (or the reading order list), use the up and down arrow keys to move between rows, press enter to select the row (shift+enter adds it to the selection) and f2 to rename it. each row's buttons say which item they are for, for example hide begin on stage and lock begin, so a screen reader can tell them apart.","set the reading order a screen reader reads a screen in a set order, and the tab key moves through buttons in the same order. by default that order follows the layers, back to front, which is not always the order that makes sense (for example, the heading might be in front but should be read first). to change it, open the layers panel and switch from layers to reading order. select an item and press read earlier or read later (or drag it), until the list reads the way you want the screen read, first to last. this does not change what is in front. a new item is read last, and a copy is read right after the item it was copied from. use layer order again puts it back. applying a template to a screen resets its reading order.","small screens and the phone view on a narrow window, such as a phone, every screen reflows into one column that reads from the top, wraps its text and can be zoomed, instead of shrinking the whole 16:9 picture. words that sit on a card stay on that card, a speech bubble keeps its text, and a shape that is only decoration is left out. see it: press ▯ phone view in the live preview. the preview is shown inside your course player, with its title, progress, controls and captions, so what you see is what a learner gets. the buttons then read upright and sideways (hold the phone either way) and full screen (back to the normal preview). a screen that keeps the scaled picture on a sideways phone shows that way in the sideways view. reading order decides the order. check it in the reading order list (it is the same list screen readers use). put the heading first and the buttons where they belong. cards and panels: put the words on a shape to make a card. in the reflowed page the card is a box holding those words. turn it off for the whole course: in player…, untick on a small screen, lay each screen out one item after another. keep one screen as drawn: select the screen and tick keep this screen as drawn on small screens. use it for a map or similar, where the layout is the point. check course warns about both choices because a screen kept as drawn cannot be zoomed. on a narrow screen, fade-in and fade-out animations still play, but movement, size changes, keyframes and appear-later timing do not: everything is shown in place. a phone held sideways also gets this one-column page, since the scaled picture would be tiny. captions stay just above the control bar as the page scrolls, and in the preview's phone view they stay at the bottom of the phone frame.","make a screen respond (triggers) use a trigger when something should happen on a screen without sending the learner to another screen: a hint that opens, a note that appears, a counter that goes up. wires on the flow canvas still decide where the course goes next. the triggers panel for a screen: each trigger reads as a sentence, with when, an optional only if test, and a numbered list of actions such as change a variable and show an overlay select the screen on the flow canvas, then open build → triggers. select + trigger. a trigger reads like a sentence at the top: when the learner selects show a hint: show hint note. choose when: the learner selects an item, the screen starts, or a variable changes (to anything, or to one value). plugins can add their own choices at the end of the list, with their own settings. optional only if: a test that must be true, such as clicks >= 3. under then, add actions: show, hide or show/hide an item; change a variable; or continue along an exit. plugins can add their own actions at the end of the list. they run in order. use the arrows to reorder. if a trigger uses a plugin that is not installed, it is kept as it is and does nothing until the plugin is back. the check before you publish warns you about it. hide something until it is needed. select the item on the stage and choose hidden at start in the floating palette. a trigger can show it later. a hidden item is not in the tab order and a screen reader does not read it until it is shown. send the course on from a trigger. add the action continue along an exit and name it, for example next. the screen's card on the flow canvas gets an exit: next socket. connect it to the next screen as you would a button. this is how \"open all three tips, then continue\" moves on. items that only a trigger uses do not need a wire. the not connected warning is not shown for them. the checks tell you when a trigger uses an item that is gone, when it waits for something that does not act as a button, and when an item is hidden but nothing shows it. the live preview and the exported course both run triggers.","add overlays (pop-up style or panel style) an overlay is a set of items that sits on top of a screen and appears when you say so. use one for a definition, a hint, a photo that opens larger, or a set of tabs, without making a screen of its own for each. there are two styles: pop-up style: the screen behind goes dim and cannot be used until the pop-up is closed. keyboard focus moves into it, escape closes it, and focus goes back to where the learner was. panel style: it sits on the screen and the rest stays usable. good for tabs and notes. editing a pop-up overlay: the strip above the stage lists screen and each overlay, with the overlay's name, style, shown at start and pause the screen settings, and the pop-up drawn over a faint copy of the screen select the screen, then use the strip above the stage: + overlay…, then pop-up style or panel style. you can change the style later. the stage now shows that overlay, with the screen faint behind it. add text, pictures, shapes and buttons as usual. they belong to the overlay. choose screen in the strip to go back to the screen itself. open build → triggers and add a trigger: when the learner selects (a button on the screen), show overlay (your overlay). give the way out: add a button on a pop-up and a trigger when the learner selects (it), hide overlay. if you forget, the player adds a close button, and escape always works. tabs. make a panel-style overlay for each tab and a button for each. each button's trigger hides the other overlays and shows its own. make learners look at everything. in a trigger, tick only if these overlays have been shown and choose all of them. for example, show the continue button only when every tab has been opened. static or animated. an overlay is static to start with: its items appear at once, without effects or sound. to animate it, choose the overlay in the strip and tick own timeline. a timeline for that overlay opens under the stage. set when its items appear, add animations and keyframes, put sound and captions on it, and drop markers on it, the same way as on a screen's timeline. it plays each time the overlay is shown. when shown again decides what happens the next time the overlay is shown: start over (the usual choice) or pick up where it left off. a trigger can wait for the timeline of (your overlay) ends, or for one of its markers. while the overlay is in front, the player's play button, seek bar and captions work on its timeline. when it closes, they go back to the screen's. good to know. switch on pause the screen if the screen's animation or narration should wait while the overlay is showing. if an overlay has its own sound and the screen has sound too, check course warns that the two can play at once unless pause the screen is on. deleting an overlay deletes the items and markers on it and the triggers that used them, and one undo brings them back.","add a shadow to text, pictures and shapes a shadow makes an item stand out from what is behind it. it only decorates: it is drawn outside the item, so nothing moves or changes size, and screen readers ignore it. select a text box, a picture or a shape. buttons do not have shadows. click shadow in the tools beside the item (the floating palette, or the row of tools if you docked it), or find shadow in properties. both show the same settings. tick show a shadow. change what you like: • color: pick a theme color or any other color. black is the default. • right and down: how far the shadow falls, in pixels. use a negative number to move it left or up. • blur: how soft the edge is. 0 is a hard edge. • opacity: how strong it is, from 0% to 100%. the shadow follows the real shape. a shadow on text goes behind the letters, and a shadow on a picture with see-through parts follows the picture, not its box. it is also copied when you copy, paste or duplicate the item, and it stays on small screens. good to know. every item starts with the shadow off. a shadow is cut off at the edge of the screen, so leave some room if an item is close to it. keep it soft and light behind text: a strong, dark shadow can make words harder to read.","change how an item looks (states) a state is another way an item can look. a button can look different when the pointer is over it, once it has been chosen, or when it is locked. a state changes the look only: color, outline, see-through level or which picture shows. it never changes the words or moves anything. select an item, then find states at the bottom of properties. add a state: hover, selected, visited, disabled, or your own. change what you want to look different, such as the fill or the text color. anything you leave alone stays as it is in normal. use show on stage to see the item in that state while you work. it is only a view; nothing is saved by looking. what each one does: hover shows while the pointer is over the item, and also while the item has keyboard focus, so people using the keyboard get the same feedback. visited shows after the learner has chosen the item once on this visit to the screen. selected, disabled and your own states show when a trigger asks for them. in triggers, add the action put an item in a state. for example: when the learner selects option a, put option a in the selected state. choose normal to put an item back. disabled also stops the item being chosen. it stays on the screen and a screen reader says it is unavailable. use it to lock a button until something else has happened. make a change people can see without color. some people cannot tell colors apart, so when it matters also change the outline or the words. the checks before publishing look at the colors of every state, and warn when text is hard to read. a disabled item is not checked, because it is not meant to be read as a control. selected buttons are also announced to screen readers as pressed. good to know. a state you add but no trigger ever uses (other than hover, visited and disabled) is flagged, because learners would never see it. removing a state removes the trigger actions that used it. hover is not used on a touch screen, because there is no pointer.","mark a point on the timeline (markers) a marker is a named flag on a screen's timeline. use one to make something happen at a moment in the narration or animation, such as showing a definition when the speaker says the word, or to let a button replay one part. select a screen. move the playhead on the timeline to the moment you want. choose ⚑ marker. a flag appears on the ruler. select it to give it a name, change its time, or delete it. in triggers, add a trigger: when the timeline reaches (your marker), then choose what happens, for example show an item or pause the timeline. for a replay button: when the learner selects replay, jump to (your marker), then play the timeline. sounds. the trigger action play a sound plays an audio file from your assets, and stop the sound ends it. a new sound replaces the one before, and a sound ends when the learner leaves the screen. the sound follows the player's volume and mute buttons. if a sound speaks, also put the words in the tab, section or card text, because a sound has no captions of its own. more you can do. when the timeline ends starts a trigger at the end of the screen, for example to show the continue button. pause the timeline stops where it is until the learner presses play or another trigger plays it. good to know. a marker is reached when the timeline gets there while playing, not when someone drags the playhead or a trigger jumps to it. a screen with nothing that moves or plays has no timeline to reach a marker on. a marker placed after the end of the timeline is flagged by the checks. deleting a marker also removes the triggers that used it.","add tabs, an accordion, flash cards, a timeline and more (interactions) these are ready-made starting points. to add one to a screen, select the screen and choose + interaction… in the strip above the stage (next to + overlay…). to add one as a new screen, choose interaction… in the build toolbar or the command search (ctrl+k), or right-click an empty spot on the flow canvas (it lands where you clicked). a short form asks where it goes (a new screen that is not connected to anything yet, or the selected screen) and what you want it to say: how many tabs or headings and their names and text, the two sides of a flip card, the dates and events of a timeline, the markers of a labeled graphic, the steps of a process, or the descriptions and caption of a picture. plugins can add more kinds, and they appear in the same list. leave a box blank to keep the starter wording; you can change everything on the stage afterwards. the form for adding tabs: where it goes, the screen title, how many tabs, and a name, text and optional sound for each tab tabs: tab buttons across the top, one panel each. choosing a tab shows its panel. accordion: a stack of headings. choosing one opens its text and slides the headings after it out of the way; choosing it again closes it and they slide back. in the form you choose whether the headings go top to bottom or side by side (tall strips with the label turned sideways) on computers and tablets. on a phone the choice is made for you: held upright it is always top to bottom, one column that scrolls, and held sideways it is always side by side. to make that work the accordion is built in both layouts. the stage shows only the layout you chose; the other layout's items are in the layers panel, and you change their wording there or by selecting them from layers. each accordion adds a number variable (accordion, accordion2...) that remembers which section is open; leave it alone. the accordion also turns on keep the scaled stage on a phone held sideways in the screen's properties; that is what lets the phone show the side-by-side layout. flash cards: a deck of 2 to 10 cards on one screen, for a quick review. each card has a front and a back; choosing the card turns it over. previous and next move through the deck, a line such as \"card 3 of 10\" shows where you are, and next on the last card says start over. you type the front and back of every card in the form before it is added. picture that opens larger: a small picture; choosing it opens a big one with a caption in a pop-up. timeline: 2 to 8 events in order along a line. name each with a date or a word (such as 1990), and write what happened. choosing an event shows its text in a panel below it. the events are in time order, which is also the order a screen reader reads them. labeled graphic: a picture with numbered markers. in the form, say what the picture shows and name each part (the name is what a screen reader says for the marker) and write a note about it. after it is added, choose the picture on the stage and drag each marker onto the part it labels. choosing a marker opens its note, which has a close button. a labeled graphic on the stage: a floor plan with numbered markers placed on reception, it help desk, kitchen and quiet room, and one overlay for each marker's note in the strip above process steps: 2 to 7 numbered steps shown one at a time, with previous and next. the learner can also choose a step by its number. previous is switched off on the first step and next on the last. it adds a number variable (process, process2...) that remembers which step is showing; leave it alone. an interaction is made of ordinary items, overlays and triggers, so change it the usual way. edit the words on the stage, move or restyle the buttons, add more tabs by copying a tab, its panel (triggers shows how they connect) and its trigger. to see how a tab works, open triggers: choosing a tab shows its panel, hides the others and marks the tab selected. replace the placeholder alt text on a picture with a real description. each new interaction lands in the middle of the screen, over other things. move it where you want it. add it once and copy it rather than adding it again, because every one adds its own overlays and triggers.","add a hotspot a hotspot is a clear, clickable area you place over part of a screen, for example over part of a picture. use more → hotspot, drag it over the area, and give it a name in the accessible name box of the floating palette: a screen reader reads that name, so say what happens (\"open the safety star\"). in the editor it shows as a faint blue dashed box; learners see nothing, but keyboard users get a visible outline when they tab to it. on the flow canvas, the screen gets an output named after the hotspot, which you connect like a button's. a hotspot is a rectangle for now. keep the markers in place on a phone on a phone, the items you can select on a picture (hotspots, clickable shapes, the numbered markers of a labeled graphic) are stacked as a list under the picture. to keep them over the picture instead: select the picture. in properties, under on a phone, the markers on this picture, choose keep in place over the picture. the choice only shows when the picture has markers on it. press phone view in the live preview to check it. the picture then fills the phone's width with the markers on it, scaled with it. learners can still tab to each marker and hear its name, and a small marker gets a finger-sized area around it that also selects it. this suits a picture with only a few markers, spread apart. with many markers close together, keep stack as a list under the picture. a screen set to keep this screen as drawn on small screens is not affected.","add a glossary choose build → glossary: terms and definitions (or press ctrl+k and type \"glossary\"). press add term, type the word or phrase, and write its definition. wherever that word appears in the text of a screen, learners see it with a dashed underline; selecting it opens a popup with the definition and a close button. also matches: other spellings that open the same definition, separated by commas (for example a plural, or \"lms\" for \"learning management system\"). words are matched whole and without regard to capital letters, so \"facilities\" does not match \"facility\" unless you list it. every time the word appears, not only the first time, in the text items of every screen. a term with no definition is not shown to learners; the dialog tells you how many are unfinished. do not use glossary words in text that you made into a button: a button inside a button does not work well with a screen reader.","give learners a file to download you can give learners a worksheet, a job aid or any document to save. the files travel inside your course, so this works without the internet. in triggers, choose add action then download a file, on a button's trigger (for example, when the learner selects get the job aid). choose the file, or import file… from your computer. pdf, word (.docx), excel (.xlsx), powerpoint (.pptx), text, csv and zip files are accepted, up to 30 mb each. you can also import files ahead of time with + import file… in the assets tab. give the button words that say what it gives (\"download the job aid (pdf)\"), so everyone knows before choosing it. use preview to try it. good to know. a screen reader is told \"downloading (file name)\" when it starts. the older word, excel and powerpoint formats (.doc, .xls, .ppt) and anything that can run are refused. some lms players block downloads from a course; check yours.","add narration and captions in the assets tab click + import images or audio and choose your narration file (mp3, wav, ogg, m4a or aac). click ▶ on its card to listen. select the screen, then click add on the audio card (or drag it onto the stage). it appears as a purple row on the timeline at the playhead, with its waveform. drag it to change when it starts. open the captions tab and choose one way to make captions: • ✨ auto-transcribe… (desktop app): pick a quality and click create captions. the first time, the speech model downloads once (45 to 260 mb); after that it works offline and nothing is uploaded. • type them while you listen: play the timeline and press + caption at playhead at each line, then type the text. • import srt / vtt… if you already have a caption file. read the captions against the audio and fix any mistakes. times can be edited as 0:12.5. courses with audio open with a start button (browsers require a click before sound can play). a narrated screen: the captions panel on the right lists each caption with its start and end time, and the timeline shows markers named listen, empathize and act at the moments the narrator says them","add a video you can put a video on a screen. it is a file inside your course, so it works without the internet. mp4 and webm files are supported. select a screen and choose ▶ video… above the stage (or + import video… in the assets tab and drag it onto the stage). pick the file. it appears on the stage as a picture of its first moment. move and resize it like any item. select it. in properties, give it a title (what a screen reader says), and import captions… from an srt or webvtt file. use preview to try it. the learner presses play. a video never starts by itself. triggers. in triggers, the actions play a video and pause a video let a button control it, and a video ends is an event you can wait for, for example to show a continue button once the video has been watched. use preview to try it, since a video only plays after the learner has used the page. captions. people who cannot hear the video need them, and the checks warn when they are missing. the learner turns them on in the video's own controls. good to know. keep videos small: a file over 60 mb, or a course over 100 mb, is flagged. videos from youtube or vimeo links are not supported. there is no audio description track (a second sound track that describes the pictures); if what happens on screen is not in the speech, say it in the screen's text as well.","build a quiz questions live in one question bank for the whole course. quiz nodes on the flow pull from it, so the same bank can serve your knowledge checks and your final assessment. 1. fill the question bank on the build tab press question bank…. add a category for each group you want to pull separately, for example knowledge check 1, knowledge check 2, knowledge check 3 and final. pick a category and press + add question. type the question, choose the type (see other kinds of question below, or one a plugin adds, which brings its own settings), enter the answers and mark which is right (a dot for one right answer, ticks for several). set points, tries (1 to 3) and shuffle the answers if you like (with shuffling on, mix the answers again on try again gives a new order on each try; left off, try again keeps the order the learner first saw. it is switched off, with a note saying why, while tries is 1, because the learner gets no second try), plus feedback for each answer and a message for right and wrong. to move a question, open it and change its category. a question sits in one category. the question bank dialog: categories on the left with how many questions each holds, and every question with its category on the right other kinds of question. besides single answer, multiple answers and true or false, choose one of these in the type list. for the lists, type one entry on each line. matching: write pairs as item | its match, such as dog | barks. the learner chooses each item's match from a list. drag and drop: the same pairs. the learner drags each item onto its target. without a mouse they press enter on an item to pick it up and enter on a target to put it down. put in order: write the steps in the right order. the learner sees them mixed up and uses the arrow buttons (or drags) to put them right. click on the picture: choose a picture, say what it shows, and list its parts as name | left, top, width, height, all as percentages of the picture, with a star in front of each right one, such as * saddle | 10, 20, 30, 15. add some wrong parts too. the learner clicks a part, or chooses one by name from a list. number: the learner types a number. set the right answer, how far off it may be (0 means exact) and a unit such as kg, shown beside the box. slider: the learner moves a slider. set the lowest and highest value, how much each move changes it, the right answer, how far off it may be, and a unit. the arrow keys move it. rating scale (likert): one statement the learner rates on a scale you write, from lowest to highest (it starts as strongly disagree to strongly agree). rating grid: several statements on one screen, each rated on the same scale. what the lms is told. in a scorm or cmi5 package, each time a learner finishes a question the course also tells the lms what they answered: which choice, which matches, which order, or which point on a rating scale, and whether it was right (ratings are reported with no right or wrong). most lmss show this in a report: in moodle, open the scorm activity, choose reports then interactions report, or track details for one learner. nothing extra is needed in your course. a web package sends nothing, because there is no lms to receive it. the wording of long answers is cut to what scorm allows, and what you type is not read by the lms as anything but text. use the answer later. on a single answer, true or false or rating question, save the answer in a variable keeps what the learner chose, so the course can act on it. first add a variable in the variables panel: a number variable gets the place of the choice (1 for the first, 2 for the second...), a text variable gets its wording, and a yes or no variable (true or false only) gets yes for the first choice. then pick it in the question. after the question, add a condition that tests the variable to send learners down different paths, for example role equals 1 goes to the manager screens. any screen can also show it: put {{role}} in its text. it is off unless you choose a variable. the two rating questions have no right answer. they are not scored, have no points or tries, never count toward the pass mark, and after answering the page says your answer is recorded. the answer is still sent to the lms (with no right or wrong), and a rating scale question can keep it in a variable with save the answer in a variable, like any single answer question. 2. add a quiz to the flow press quiz on the build tab. a quiz node and a results page appear, wired together. (if the bank is empty you get three sample questions.) question adds a single question written on the node instead. wire the screen before it to the quiz's show socket, passed on to a complete node, and failed to a screen that explains what to do next. select the quiz node. under questions come from tick the categories to use (none ticked means all). choose ask all, or ask only a number picked at random. when you ask only some from two or more categories you can tick take a set share from each category and give each a percentage. a quiz node's settings: the categories it draws from, ask only 8 at random with a set share from each category, random order, and the introduction page an introduction page. select a quiz node and tick show a page before the first question under introduction page. type a title (blank uses the quiz's name) and what the learner should know or do. the page also says how many questions there are and has a start button. it is off unless you tick it. design the question page. select any question or quiz node: the stage shows the question page for the whole course. one design serves every question in every quiz, so a change here changes them all (except a quiz or question that has its own design; see below). the page has these items, drawn with sample words: the progress line (question 1 of 5), the question text, the answer choices, the feedback box, and the submit, next question and try again buttons. next question shows continue on the last question, and try again only when the learner has tries left. submit sits in front of the other two, because it is the one learners see first; use the layers panel to pick the ones behind it. drag an item to move it, and use its handles to resize or turn it, as on a screen. style it in the floating palette or in properties: text size (0 uses the course's size), alignment of the progress line and question text, text color, the background of the choices and the feedback box, and the color of each button. a button's words are drawn in black or white, whichever reads best on its color. nothing can be added to the question page yet, and its items cannot be copied. some items can be removed; see remove an item from a quiz page below. a new course starts with a design that looks like the standard page, so you only need this if you want a different layout. press preview to see it with your real questions. on a phone the items stack in one column, in reading order, whatever their places on the stage. choices are always real radio buttons or check boxes, submit stays off until something is picked, and feedback is announced to screen readers, whatever the layout. the question and the feedback grow downward when their text is long, and the choices scroll. the part that grows can slide under the item below and be hidden, so leave room under them and check the preview with your longest question. check course warns when a question or its feedback is probably too long for its box. design the introduction page. the introduction page also has one design for the whole course. there are two ways to open it: select a quiz node and press introduction page in the bar above the stage. press question page to go back. or, in the quiz node's properties, with show a page before the first question ticked, press design the introduction page. the stage then shows the introduction page with sample words: the quiz title, the instructions, the number of questions and the start button. each quiz fills in its own title, instructions and number of questions when the course runs. move, resize and style the items as on the question page: text size (0 uses the course's sizes; the title uses heading 1), alignment, text color, and the color of the start button. start's words are drawn in black or white, whichever reads best on its color. a change here changes the introduction page of every quiz. if the note above the stage says the selected quiz does not show it, tick show a page before the first question to switch it on for that quiz. nothing can be added to the introduction page yet, and its items cannot be copied. the title, instructions and number of questions can be removed (see below). when you select another node, the stage goes back to the question page. on a phone the items stack in one column: title, instructions, number of questions, start. the title, instructions and number of questions grow downward when their text is long and can slide under the item below, so leave room under them. 3. choose what each results page shows select a results page. under show the results of pick all quizzes that count toward the score, or only these and tick the quizzes it should total. the node on the canvas says which. set the pass mark as a percentage (blank uses the course's mastery score, or 80%). tick let learners retry and wire the retry socket back to the quiz. retry clears only the answers that page was showing. tick show each question to let learners review their answers. to report the score to the lms, select the complete node and set score variable to quizpercent with min 0 and max 100. design the results page. select any results node: the stage shows the results page for the whole course. one design serves every results page, so a change here changes them all. the page has these items, drawn with sample words: the heading (your results and the page title), the score (the percentage, the number right and the points), the pass or fail message, the answer review, and the continue and try again buttons. the answer review shows only when show each question is ticked, and try again only when let learners retry is ticked and the learner did not pass. move, resize and style the items as on the question page: text size, alignment of the heading, score and message, text color, the background of the review rows, and the color of each button. the page title, the pass and fail messages and the button words are still typed on the results node. the pass or fail message stays green or red, and its words say whether the learner passed. on a dark background it uses a lighter green or red, so it stays easy to read. nothing can be added to the results page yet, and its items cannot be copied. the heading, score, message and answer review can be removed (see below). a new course starts with a design that looks like the standard page. press preview to see it with a real score. on a phone the items stack in one column, in reading order. the heading, the score and the message grow downward when their text is long, and the review scrolls; learners can scroll it with the keyboard too. the part that grows can slide under the item below and be hidden, so leave room under them. a design for one quiz, question or results page. each quiz page normally uses the course design. to give one node a layout of its own: select the quiz, question or results node (for a quiz's introduction page, also press introduction page above the stage). in the note above the stage, press use a design for this quiz only (this question only, this results page only). it starts as a copy of the design the page uses now. move, resize, style and remove items as usual. the note now says the design is for this quiz only, and changes there apply only to it; the course design and every other quiz stay as they were. the node's properties say this quiz uses its own question page design. • a quiz node can have its own question page and its own introduction page. the questions it pulls from the question bank use its question page. • to go back, press use the course design again in the note. it asks first, because the quiz's own design is thrown away. undo brings it back. start a quiz page from a template. a template is a ready-made layout for one kind of quiz page. select the quiz, question or results node (for a quiz's introduction page, also press introduction page above the stage). in the note above the stage, press templates…. the list shows the templates for that page: the ones that come with the app (classic, wide choices for the question page, big buttons, centered and side by side), then any a plugin adds, then the ones you saved. press use this design under the one you want. the next step says what will change: where each item sits, its size, text size and colors, and which items are removed. press use this design again to apply it, or cancel to go back to the list. • on the course design, quizzes, questions or results pages with a design of their own keep it. the confirm step says how many there are and offers also switch … to this template. tick it to switch them too; their own design for that page is deleted (a quiz keeps its own introduction page when you apply a question page template). • on a design for one quiz, question or results page, only that node changes. • one undo brings everything back. the words, choices and buttons a learner uses do not change. • the narrower layouts (centered, side by side) fit fewer words on a line. if check course then warns that text runs over the item below, make the box taller, the text smaller or the wording shorter. save a quiz page design as a template. press save as template… in the note above the stage, type a name and press save template. it keeps where each item sits, its size, text size and colors, and which items are removed; it does not keep locks, groups or items hidden while editing. it is offered under templates… above that kind of page in every course on this computer. press ✕ on one of your templates to delete it; the ones from the app and plugins cannot be deleted. remove an item from a quiz page. select an item on the stage and press delete, or press the bin next to it in the layers panel. these items can be removed: the progress line and the feedback box (question page), the heading, the score, the pass or fail message and the answer review (results page), and the quiz title, the instructions and the number of questions (introduction page). the question, the answer choices, submit, next question, continue, try again and start cannot be removed: learners need them to use the page. pressing delete on one says so. removed items are listed in the note above the stage, for example removed: feedback box. press put back next to one to return it to its standard place. the same list is at the bottom of the layers panel. undo works for both. with the keyboard, focus moves on to the next bin or put back button, so you keep your place. removing works on the course design and on a quiz's own design. a removed feedback box or pass or fail message is still read out to screen reader users, but sighted learners no longer see whether they were right (apart from the marks on the choices) or whether they passed. only remove them when something else on the page or in the course tells learners. what check course says about quiz pages. check course looks at each quiz page design your course uses (the course design and each node's own) and warns, without stopping you from publishing, when: the feedback box or the pass or fail message has been removed, so sighted learners are not told whether they were right or passed; a text color or background you picked for an item is hard to read (for example light text on a light choice background). buttons are not checked, because their words are always black or white; a question, its feedback, a quiz title, instructions, a results heading, the score (for example after making it bigger) or a pass or fail message is probably too long for its box and runs over the item below it. this is an estimate from the number of letters and the text size, so always check the preview. to fix it, make the box taller, the text smaller or the words shorter. when many questions are too long, check course lists the first one and says how many more there are. click a finding to open that page on the stage. example: three knowledge checks and a final categories: knowledge check 1, 2, 3, and final (or reuse the three check categories for the final). after each lesson add a quiz node pulling that check's category. untick counts toward the quiz score so it is practice. give it its own results page set to show just that quiz. at the end add a quiz node that ticks all the check categories, asks 10, and takes a share from each. leave it scored. its results page shows all quizzes that count toward the score, with the pass mark and retry, and passed goes to complete. the practice checks never affect the score reported to the lms. good to know the quiz keeps quizpoints, quizpossible, quizpercent, quizcorrect and quizasked up to date, for scored quizzes only. use them in a condition (for example, quizpercent >= 50 for a remedial screen) or in text such as {{quizpercent}}%. where `{{variable}}` works. in a text item, a button's label, an image's alt text, a video's title and an item's accessible name (the name a screen reader gives it). it does not work in screen titles, the table of contents, quizzes or captions. the editing view shows the raw {{score}}; the value appears in preview and the course. a name that is not a declared variable is flagged by the checks. a screen reader is not told when a value changes; it hears the new words next time it reaches the item. if a category has fewer questions than its share, the rest come from the other categories. check course warns when the shares do not add up to 100%, when a quiz asks for more than are available, and when a question has no right answer. a multiple-answer question is right only when exactly the right answers are picked. with more than one try, the right answer is not shown until the learner is right or out of tries. learners cannot use back during a quiz, and quiz pages show in the contents but can't be jumped to. a learner who leaves mid-quiz comes back to the same question and score. a quiz page can have its own theme, like a screen (override master theme). deleting a category keeps its questions as uncategorized.","set the course look once (the master theme) click master theme… on the toolbar. pick a ready-made master, or set your own: the six colors (primary is used for buttons), background (color, gradient or a picture from your imported images), fonts (body and headings), and text sizes. every screen follows it, including template screens and screens you add later. change a master setting and all the screens update. to make one screen different, select it and tick override master theme in the properties tab. the color, font and background settings appear only after you tick it, and only the ones you change are overridden; click the ↺ beside a setting to go back to the master. untick the box to return the whole screen to the master. on the stage, the color / fill / text buttons show the theme colors first. pick a theme color and it will follow the master if you change the theme colors later. auto means \"use the master\". if text is hard to read on the background, the dialog and the validation tab warn you.","design the player click player… on the toolbar. pick a style (midnight, daylight, ocean, high contrast, minimal), then change colors, shape, which buttons appear (menu, back, next, play/pause, replay, seek bar, time, speed, volume, captions, full screen) and caption size and colors. the preview on the right is the real player. everything is saved with the course and used by every export format. button shape changes how the control bar buttons look: round (filled circle), rounded square (filled), square outline (a thin border, no fill) and ghost (the icon on its own, with no background or border until a learner points at it or tabs to it). the play / pause button stays filled with the accent color in every shape. on a phone, buttons are at least 44 by 44 pixels. the course player dialog: ready-made looks, colors, shape and layout settings on the left, and a live preview of the player with its control bar and a sample caption on the right","add a table of contents open player… (design tab) and, under table of contents, tick show a table of contents. choose the side (left or right), the heading, the width, whether it is open at the start, and whether entries are numbered. to leave a screen out, or give it a different name in the list, select the screen and use in the table of contents in properties. learners can hide the list with its ✕ button and bring it back with the contents button on the control bar. they can open only screens they have already visited.","check the course for problems the validation panel lists everything the checks find, as you work. open it from the right-hand rail, or choose publish → check the course for problems. errors (codes starting val-e) stop the course from being exported: a missing wire from start, a variable that does not exist, a formula that cannot be read, fast flashing over a large area, and so on. warnings (val-w) do not stop an export, but say what a learner may run into: a missing alt text or caption, a button with no wire, text that is hard to read on its background, a reading order that runs against how a screen looks. select a finding to go to the card, and the item, it is about. with the keyboard, tab to a finding and press enter. text laid over a shape or box (a pop-up's words on its white box, for example) is checked against the color of that shape, not only the page background. if the words are hard to read on it, the warning names the text and the shape: change the text color or the shape's fill. the export dialog shows the same checks for the format you chose (see publish the course (export)).","motion, flashing and sound check course looks at how things on each screen really move over time, and tells you when something could be a problem for learners: finding what it means how to fix it error: an item flashes more than 3 times a second and covers a large part of the screen fast flashing over a large area can cause seizures. you cannot export until it is fixed. slow it down (fewer fade in and out changes, or longer effects), or make the item smaller. warning: a smaller item flashes more than 3 times a second it is hard to read around and distracting. keep it to 3 flashes a second or fewer. warning: movement starts by itself and lasts over 5 seconds, and the play / pause button is off learners cannot stop it. turn play / pause on in the player designer, or shorten the movement. warning: sound starts by itself and lasts over 3 seconds, and play / pause and volume are both off learners cannot stop it or turn it down. turn one of those buttons on in the player designer. with the player's normal settings you will not see the last two. learners who have asked their computer for less motion see every item at rest, with no effects. a course that has sound starts from a start button that the learner presses (a course without sound starts straight away), and a screen never moves on by itself. the check works from what the item really does, so it also covers effects added by plugins.","check accessibility before you publish in the export dialog, press check accessibility of the finished course. knowledgefoundry builds the course, opens it the way a learner's browser would, and an automatic checker (axe-core) looks at every screen, quiz and results page and the player around each (up to 40 pages). it lists what it finds, worst first, naming the screens each problem is on, with how many places and an example. a course with many screens takes a little while. if a problem is on every page it comes from the course player, so it is listed once. these are warnings; they never stop you from exporting. the same check runs after you export. reading order. check course also warns when a screen reader would read a screen in an order that clearly differs from how it looks (for example the footer note before the heading). to change it, open the layers panel and use reading order. the order also decides how the screen is stacked on a phone. an automatic check finds only some problems. also try your course with only a keyboard (tab, enter, space), and with a screen reader such as nvda or narrator.","publish the course (export) choose file → export… (ctrl+e), or export course on the publish tab. the export course dialog: the four package formats, the course title, pass or complete rule and mastery score, and the checks for the chosen format pick a package format. • cmi5: for a modern lms or learning record store. reports completion, pass or fail and score, resumes where the learner left off, and the pass or complete rule is built into the package. • scorm 2004 (4th edition): for most lmss. the pass or complete rule is set in your lms. • scorm 1.2: the widest compatibility. one status (passed, failed or completed), a score from 0 to 100, and limited resume data. • web (html5): no lms. open index.html, share a folder or host it anywhere. nothing is tracked, so it suits review copies and demos. check the course settings: the title, the pass or complete rule (for scorm, set the same rule in your lms) and the mastery score as a percentage. read the checks. errors must be fixed first; show takes you to the problem. check accessibility of the finished course runs the automatic accessibility check (see check accessibility before you publish). press export, and choose where to save the package. show in folder opens it in explorer. the format you chose is remembered for next time. exporting never changes your project file.","plugins plugins add things to knowledgefoundry: new kinds of items for the stage, new flow steps, animations, player looks. some come with the app (see help → plugins…); you can add others. add a plugin: open help → plugins… → open plugins folder and put the plugin there, either as a folder or as a zip (it has a plugin.json and an index.js inside). choose look again. if it does not load, it is listed under not loaded with the reason. use it in a course: tick use in this course next to the plugin. a plugin the course does not list is not used. the course remembers which plugins and versions it uses. choose a version: if more than one version of a plugin is installed, pick the one this course should use. the plugins that come with the app are always on; only the version can change. export: a course carries the code of the plugins it uses, so they work for learners. what a plugin can add: new items for the stage, flow steps, animations and keyframe properties, player buttons, panels and looks, ways to publish (export targets) and extra steps when publishing, extra checks in check course, screen templates, quiz page templates, ready-made masters, fonts and backgrounds, places to find images and sounds, converters for other file types, ways to turn speech into captions, caption file formats and styles, and ways to score a quiz or show its results. only keep plugins you trust in the folder. a plugin runs with the same access as the app. isolation is planned but not built yet. permissions. a plugin lists what it needs, such as contacting the internet, reading files, or putting its own code in your published courses. help → plugins… shows these in plain words next to each plugin, and marks the sensitive ones. read them before you tick use in this course. the app refuses a plugin that does something it did not list. this is not yet a wall: until plugins run in isolation, only keep plugins you trust. if a plugin causes trouble, use safe mode. choose help → restart in safe mode (or the same button in help → plugins…). the app starts again with only the plugins that come with it, each at its newest version, and it does not look in the plugins folder. your course file is not changed, so you can open it, fix or remove the plugin, and choose help → restart normally. in safe mode the plugin choices are switched off, and a course that uses plugins from the folder cannot be exported until you restart normally. if the app will not open at all, start it with --safe-mode added to the shortcut's target.","keyboard shortcuts help → keyboard shortcuts (ctrl+/) shows this list in the app. keys what they do ctrl+n, ctrl+o, ctrl+s, ctrl+shift+s new project, open, save, save as ctrl+e export ctrl+k search commands f1 user guide ctrl+z; ctrl+y or ctrl+shift+z undo; redo ctrl+c, ctrl+x, ctrl+v copy, cut, paste items ctrl+d; delete duplicate; delete the selection ctrl+a select everything on the screen ctrl+g; ctrl+shift+g group; ungroup arrow keys (shift for 10 px) nudge the selection alt+arrow keys (add shift to add to the selection) select the next or previous item alt while dragging switch off snapping [ and ] send backward, bring forward space (timeline) play or pause space and drag (flow canvas) pan","need help or version details? help → user guide (or f1) opens this guide inside the app, with its sections listed down the side. help → take the tour replays the one-minute tour of the window that shows the first time the app opens. help → example courses opens one of the finished example courses (see example courses). help → report a bug… opens the bug report form in your browser, where you can describe what went wrong and attach a screenshot; please send every bug this way. help → send feedback… opens the feedback form for ideas and opinions. help → license… shows the terms for using knowledgefoundry. open help → about knowledgefoundry (or click the version at the bottom right). copy these details gives your version and system information to paste into a support request, and open data folder shows where the app keeps your layout, templates and downloaded speech models. the about box also shows who created the app (jason skocilich) and the copyright notice."];

  document.addEventListener('DOMContentLoaded', function () {
    var group = document.querySelector('.look');
    if (group) {
      group.hidden = false;
      var buttons = group.querySelectorAll('button');
      var mark = function (look) {
        for (var i = 0; i < buttons.length; i++) buttons[i].setAttribute('aria-pressed', String(buttons[i].getAttribute('data-look') === look));
      };
      mark(saved === 'light' || saved === 'dark' ? saved : 'system');
      group.addEventListener('click', function (e) {
        var b = e.target.closest ? e.target.closest('button') : null;
        if (!b) return;
        var look = b.getAttribute('data-look');
        applyLook(look);
        mark(look);
        try { if (look === 'system') localStorage.removeItem(KEY); else localStorage.setItem(KEY, look); } catch (err) { /* not saved */ }
      });
    }

    var nav = document.getElementById('sections');
    var toggle = document.querySelector('.toggle');
    if (nav && toggle) {
      toggle.hidden = false;
      nav.classList.add('collapsed');
      toggle.addEventListener('click', function () {
        var open = nav.classList.toggle('collapsed') === false;
        toggle.setAttribute('aria-expanded', String(open));
      });
    }

    var box = document.getElementById('q');
    var count = document.getElementById('count');
    if (nav && box && count) {
      box.parentNode.hidden = false;
      var items = nav.querySelectorAll('li[data-i]');
      box.addEventListener('input', function () {
        var q = box.value.trim().toLowerCase();
        var n = 0;
        for (var i = 0; i < items.length; i++) {
          var at = Number(items[i].getAttribute('data-i'));
          var show = !q || (TEXT[at] || '').indexOf(q) !== -1;
          items[i].hidden = !show;
          if (show) n++;
        }
        count.textContent = q ? n + ' section' + (n === 1 ? '' : 's') + ' found' : '';
      });
    }
  });
})();
